@RestController
@RequestMapping("/api/products")
public class ProductController {
    private final ProductService productService;

    public ProductController(ProductService productService) {
        this.productService = productService;
    }

    @GetMapping
    public List<ProductDTO> getAllProducts() {
        return productService.findAll(); // Service layer handles business logic
    }
}

@Service
public class ProductService {
    private final ProductRepository productRepository;

    public ProductService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    public List<ProductDTO> findAll() {
        var products = productRepository.findAll();
        return products.stream()
            .map(this::toDTO) // Convert entities to DTOs
            .toList();
    }

    private ProductDTO toDTO(Product product) {
        return new ProductDTO(product.getId(), product.getName(), product.getPrice());
    }
}

@Repository
public interface ProductRepository extends JpaRepository<Product, Long> {
    // Spring Data JPA provides basic CRUD operations automatically
}

// PRESENTATION TIER: Handles HTTP requests and responses
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    @PostMapping
    public ResponseEntity<OrderDTO> createOrder(@RequestBody OrderRequest request) {
        var order = orderService.placeOrder(request); // Delegates to application tier
        return ResponseEntity.status(HttpStatus.CREATED).body(order);
    }
}

// APPLICATION TIER: Contains business logic and rules
@Service
public class OrderService {
    private final OrderRepository orderRepository;
    private final InventoryService inventoryService;

    @Transactional
    public OrderDTO placeOrder(OrderRequest request) {
        // Business rule: check inventory before placing order
        if (!inventoryService.isAvailable(request.productId(), request.quantity())) {
            throw new OutOfStockException("Product not available");
        }
        var order = new Order(request.productId(), request.quantity(), LocalDateTime.now());
        var savedOrder = orderRepository.save(order); // Delegates to data tier
        inventoryService.reduceStock(request.productId(), request.quantity());
        return toDTO(savedOrder);
    }
}

// DATA TIER: Handles database operations
@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByCustomerId(Long customerId);
}

