@Entity
@Table(name = "tasks", indexes = @Index(name = "idx_task_owner", columnList = "ownerId"))
class Task {
    @Id @GeneratedValue private Long id;
    @Column(nullable = false) private Long ownerId;
    @Column(nullable = false) private String title;
    @Enumerated(EnumType.STRING) private TaskStatus status;
    protected Task() {}              // required by JPA
    // domain methods and accessors omitted
}

interface TaskRepository extends JpaRepository<Task, Long> {
    Page<Task> findAllByOwnerId(Long ownerId, Pageable page);
    Optional<Task> findByIdAndOwnerId(Long id, Long ownerId);
}

@Service
class TaskService {
    private final TaskRepository tasks;

    @Transactional
    TaskResponse rename(Long ownerId, Long taskId, String title) {
        Task task = tasks.findByIdAndOwnerId(taskId, ownerId)
            .orElseThrow(TaskNotFoundException::new);
        task.rename(title);
        return TaskResponse.from(task);
    }
}

